export const contextArchitectureSources = seeds.map(([id, category, body, , , , access], index) => ({
  id, family: `context-v1-${id}`, category, split: index % 6 < 3 ? 'development' as const : 'holdout' as const,
  path: `Evaluation/${id}.md`, body: `# ${id}\n\n## Requirement\n${body}\n`, access: access ?? 'allowed',
}));
export const contextArchitectureTasks = seeds.flatMap(([id, category, , queries, required, tools, access, noAnswer], index) => queries.map((query, languageIndex) => ({
  id: `${id}-${['ko', 'en', 'mixed'][languageIndex]}`, family: contextArchitectureSources[index]!.family,
  split: contextArchitectureSources[index]!.split, language: ['ko', 'en', 'mixed'][languageIndex]!, category, query,
  expectedDocuments: noAnswer ? [] : [`Evaluation/${id}.md`], requiredHeadings: noAnswer ? [] : ['Requirement'],
  requiredEvidence: required, allowedTools: tools, expectedWarnings: required, noAnswer: noAnswer ?? false,
  forbiddenDocuments: access ? [`Evaluation/${id}.md`] : [],
})));
